  const url = 'https://api.example.com/posts';

  const res = await fetch(url, {
    next: { 
      revalidate: 3600,
      tags: tags || []
    }
  });

  if (!res.ok) {
    throw new Error('Failed to fetch posts');
  }

  return res.json();
}

